require('dotenv').config();
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3001;

app.use(express.json({ limit: '10mb' }));

const DATA_DIR = path.join(__dirname, 'data');
const PRESETS_DIR = path.join(DATA_DIR, 'presets');
const SESSIONS_DIR = path.join(DATA_DIR, 'sessions');

[DATA_DIR, PRESETS_DIR, SESSIONS_DIR].forEach(dir => {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
});

// Read keys from env (server-side only, never exposed to client)
const OPENROUTER_KEY = process.env.OPENROUTER_KEY || '';
const ELEVENLABS_KEY = process.env.ELEVENLABS_KEY || '';

function readAllFiles(dir) {
  try {
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.json'));
    return files
      .map(f => {
        try { return JSON.parse(fs.readFileSync(path.join(dir, f), 'utf-8')); }
        catch { return null; }
      })
      .filter(Boolean)
      .sort((a, b) => (b.savedAt || b.startTime || 0) - (a.savedAt || a.startTime || 0));
  } catch { return []; }
}

// === STATUS (tell client which services are configured, no key exposure) ===

app.get('/api/status', (req, res) => {
  res.json({
    openrouter: Boolean(OPENROUTER_KEY),
    elevenlabs: Boolean(ELEVENLABS_KEY),
  });
});

// === PRESETS ===
app.get('/api/presets', (req, res) => res.json(readAllFiles(PRESETS_DIR)));
app.post('/api/presets', (req, res) => {
  const preset = req.body;
  if (!preset.id) return res.status(400).json({ error: 'Missing id' });
  fs.writeFileSync(path.join(PRESETS_DIR, `${preset.id}.json`), JSON.stringify(preset, null, 2));
  console.log(`[Preset saved] ${preset.name}`);
  res.json({ ok: true });
});
app.delete('/api/presets/:id', (req, res) => {
  try { fs.unlinkSync(path.join(PRESETS_DIR, `${req.params.id}.json`)); } catch {}
  res.json({ ok: true });
});

// === SESSIONS ===
app.get('/api/sessions', (req, res) => res.json(readAllFiles(SESSIONS_DIR)));
app.post('/api/sessions', (req, res) => {
  const session = req.body;
  if (!session.id) return res.status(400).json({ error: 'Missing id' });
  fs.writeFileSync(path.join(SESSIONS_DIR, `${session.id}.json`), JSON.stringify(session, null, 2));
  const label = session.type === 'live' ? `P${session.participantNumber}` : 'Chat';
  console.log(`[Session saved] ${label} (${session.messages?.length || 0} messages)`);
  res.json({ ok: true });
});
app.delete('/api/sessions/:id', (req, res) => {
  try { fs.unlinkSync(path.join(SESSIONS_DIR, `${req.params.id}.json`)); } catch {}
  res.json({ ok: true });
});

// === OPENROUTER CHAT PROXY (streaming) ===

app.post('/api/chat', async (req, res) => {
  if (!OPENROUTER_KEY) {
    return res.status(503).json({ error: { message: 'OpenRouter key not configured on server' } });
  }

  try {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${OPENROUTER_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': req.headers.origin || 'http://localhost',
        'X-Title': 'ConAI AINA LLM Tester',
      },
      body: JSON.stringify(req.body),
    });

    res.status(response.status);
    const contentType = response.headers.get('content-type') || 'application/json';
    res.setHeader('Content-Type', contentType);

    if (req.body.stream) {
      response.body.pipe(res);
    } else {
      const data = await response.json();
      res.json(data);
    }
  } catch (err) {
    console.error('[OpenRouter proxy] Error:', err.message);
    res.status(502).json({ error: { message: err.message } });
  }
});

// === ELEVENLABS TTS PROXY ===

app.post('/api/tts', async (req, res) => {
  if (!ELEVENLABS_KEY) {
    return res.status(503).json({ error: { message: 'ElevenLabs key not configured on server' } });
  }

  const { voiceId, text, model, stability, similarity } = req.body;
  if (!voiceId || !text) return res.status(400).json({ error: 'Missing voiceId or text' });

  try {
    const response = await fetch(
      `https://api.elevenlabs.io/v1/text-to-speech/${voiceId}/stream`,
      {
        method: 'POST',
        headers: { 'xi-api-key': ELEVENLABS_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          text,
          model_id: model || 'eleven_multilingual_v2',
          voice_settings: {
            stability: stability ?? 0.5,
            similarity_boost: similarity ?? 0.75,
          },
        }),
      }
    );

    res.status(response.status);
    res.setHeader('Content-Type', response.headers.get('content-type') || 'audio/mpeg');
    response.body.pipe(res);
  } catch (err) {
    console.error('[ElevenLabs TTS proxy] Error:', err.message);
    res.status(502).json({ error: { message: err.message } });
  }
});

// === LOCAL MODEL PROXY (Ollama etc.) ===

app.post('/api/local-llm', async (req, res) => {
  const { endpoint, ...body } = req.body;
  if (!endpoint) return res.status(400).json({ error: 'Missing endpoint URL' });

  try {
    const url = endpoint.replace(/\/$/, '') + '/v1/chat/completions';
    console.log(`[Local LLM] ${url} (${body.model})`);

    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });

    res.status(response.status);
    res.setHeader('Content-Type', response.headers.get('content-type') || 'application/json');

    if (body.stream) {
      response.body.pipe(res);
    } else {
      const data = await response.json();
      res.json(data);
    }
  } catch (err) {
    console.error('[Local LLM] Error:', err.message);
    res.status(502).json({ error: { message: `Cannot reach local model at ${req.body.endpoint}: ${err.message}` } });
  }
});

app.listen(PORT, () => {
  console.log(`\n  ConAI API server on http://localhost:${PORT}`);
  console.log(`  OpenRouter: ${OPENROUTER_KEY ? 'configured' : 'NOT CONFIGURED'}`);
  console.log(`  ElevenLabs: ${ELEVENLABS_KEY ? 'configured' : 'NOT CONFIGURED'}`);
  console.log(`  Data dir:   ${DATA_DIR}\n`);
});

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    allowedHosts: true,
    proxy: {
      '/api': 'http://localhost:3001',
    },
  },
})

