1	import { useState, useCallback, useRef } from 'react';
2	import type { Message, LiveSessionMode, LiveSessionState, LLMParams } from '../types';
3	
4	interface UseLiveSessionOptions {
5	  model: string;
6	  compiledPrompt: string;
7	  params: LLMParams;
8	}
9	
10	export function useLiveSession({ model, compiledPrompt, params }: UseLiveSessionOptions) {
11	  const [messages, setMessages] = useState<Message[]>([]);
12	  const [sessionState, setSessionState] = useState<LiveSessionState>('idle');
13	  const [pendingResponse, setPendingResponse] = useState<string | null>(null);
14	  const [sessionStart, setSessionStart] = useState<number | null>(null);
15	  const abortRef = useRef<AbortController | null>(null);
16	
17	  const startSession = useCallback(() => {
18	    setMessages([]);
19	    setSessionState('listening');
20	    setSessionStart(Date.now());
21	    setPendingResponse(null);
22	  }, []);
23	
24	  const endSession = useCallback(() => {
25	    abortRef.current?.abort();
26	    setSessionState('idle');
27	    setSessionStart(null);
28	    setPendingResponse(null);
29	  }, []);
30	
31	  const generateResponse = useCallback(async (userText: string): Promise<string> => {
32	    const userMsg: Message = {
33	      id: crypto.randomUUID(),
34	      role: 'user',
35	      content: userText,
36	      timestamp: Date.now(),
37	    };
38	    setMessages(prev => [...prev, userMsg]);
39	    setSessionState('processing');
40	
41	    const abortController = new AbortController();
42	    abortRef.current = abortController;
43	
44	    try {
45	      const allMessages = [...messages, userMsg];
46	      const apiMessages = [
47	        { role: 'system' as const, content: compiledPrompt },
48	        ...allMessages.map(m => ({ role: m.role as 'user' | 'assistant', content: m.content })),
49	      ];
50	
51	      const response = await fetch(`${import.meta.env.BASE_URL}api/chat`, {
52	        method: 'POST',
53	        headers: { 'Content-Type': 'application/json' },
54	        body: JSON.stringify({
55	          model,
56	          messages: apiMessages,
57	          temperature: params.temperature,
58	          top_p: params.topP,
59	          max_tokens: params.maxTokens,
60	          frequency_penalty: params.frequencyPenalty,
61	          presence_penalty: params.presencePenalty,
62	          stream: false,
63	        }),
64	        signal: abortController.signal,
65	      });
66	
67	      if (!response.ok) {
68	        const err = await response.json().catch(() => ({}));
69	        throw new Error(err.error?.message || `API error: ${response.status}`);
70	      }
71	
72	      const data = await response.json();
73	      const content = data.choices?.[0]?.message?.content || 'No response generated.';
74	      return content;
75	    } catch (err: unknown) {
76	      if (err instanceof Error && err.name === 'AbortError') return '';
77	      throw err;
78	    }
79	  }, [openrouterKey, model, compiledPrompt, params, messages]);
80	
81	  // Hands-free: auto-generate and return response
82	  const handleHandsFree = useCallback(async (userText: string): Promise<string> => {
83	    const response = await generateResponse(userText);
84	    if (response) {
85	      const assistantMsg: Message = {
86	        id: crypto.randomUUID(),
87	        role: 'assistant',
88	        content: response,
89	        timestamp: Date.now(),
90	        model,
91	      };
92	      setMessages(prev => [...prev, assistantMsg]);
93	      setSessionState('responding');
94	    }
95	    return response;
