    ssl_certificate /etc/nginx/ssl/screens.ri.se.crt;
    ssl_certificate_key /etc/nginx/ssl/screens.ri.se.key;

    # --- ConAI LLM Tester (sub-path /conai) ---
    location = /conai {
        return 301 /conai/;
    }

    location /conai/ {
        alias /opt/conai/dist/;
        index index.html;
        try_files $uri $uri/ /conai/index.html;
    }

    location /conai/api/ {
        proxy_pass http://127.0.0.1:3001/api/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 300s;
        proxy_send_timeout 300s;
        proxy_buffering off;         # streaming chat + TTS
        client_max_body_size 10m;
    }
    # --- end ConAI ---

    # Existing: proxy everything else to the legacy app on :8080
    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

