  const handleManual = useCallback((userText: string) => {
    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: userText,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, userMsg]);
    setSessionState('awaiting-approval');
  }, []);

  const sendManualResponse = useCallback((text: string): string => {
    const assistantMsg: Message = {
      id: crypto.randomUUID(),
      role: 'assistant',
      content: text,
      timestamp: Date.now(),
      model: 'manual',
    };
    setMessages(prev => [...prev, assistantMsg]);
    setSessionState('responding');
    return text;
  }, []);

  // Inject system event (scenario trigger)
  const injectEvent = useCallback((content: string) => {
    const msg: Message = {
      id: crypto.randomUUID(),
      role: 'system',
      content,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, msg]);
  }, []);

  const setListening = useCallback(() => {
    setSessionState('listening');
  }, []);

  return {
    messages,
    sessionState,
    pendingResponse,
    sessionStart,
    startSession,
    endSession,
    handleHandsFree,
    handleApprove,
    approveResponse,
    rejectResponse,
    editAndApprove,
    handleManual,
    sendManualResponse,
    injectEvent,
    setListening,
  };
}

