"""Routes for session list, creation, viewing, and deletion."""
from __future__ import annotations

from pathlib import Path

from fastapi import APIRouter, Form, HTTPException, Request
from fastapi.responses import HTMLResponse, RedirectResponse
from fastapi.templating import Jinja2Templates

from app.database import get_db
from app.gps_parser import parse_gps_csv
from app.models import ReportSession
from app.parser import parse_report, seconds_to_mmss

router = APIRouter()

TEMPLATES_DIR = Path(__file__).resolve().parent.parent / "templates"
templates = Jinja2Templates(directory=str(TEMPLATES_DIR))


def _derive_video_id(video_path: Path) -> str:
    parent = video_path.parent.name
    if parent and parent.isdigit():
        return parent
    return video_path.stem


def _derive_video_start_ms(video_id: str) -> int | None:
    """Tool convention: when the folder name is a unix-ms timestamp,
    that's also the video start time, so GPS aligns to video time."""
    if video_id.isdigit():
        try:
            return int(video_id)
        except ValueError:
            return None
    return None


@router.get("/sessions", response_class=HTMLResponse)
def list_sessions(request: Request):
    db = get_db()
    rows = db.list_sessions()
    # Decorate with annotation counts
    decorated = []
    for s in rows:
        sid = int(s["id"])
        n_flags = db.connect().execute("SELECT COUNT(*) AS n FROM flags WHERE session_id=?", (sid,)).fetchone()["n"]
        n_anns = db.connect().execute("SELECT COUNT(*) AS n FROM annotations WHERE session_id=?", (sid,)).fetchone()["n"]
        cls_counts = {
            r["classification"]: int(r["n"])
            for r in db.connect().execute(
                "SELECT classification, COUNT(*) AS n FROM annotations WHERE session_id=? GROUP BY classification",
                (sid,),
            )
        }
        decorated.append({
            **s,
            "n_flags": n_flags,
            "n_anns": n_anns,
            "tps": cls_counts.get("TP", 0),
            "fps": cls_counts.get("FP", 0),
            "fns": cls_counts.get("FN", 0),
            "mis": cls_counts.get("Mis", 0),
            "video_exists": Path(s["video_path"]).exists() if s["video_path"] else False,
        })
    return templates.TemplateResponse(request, "sessions_list.html", {"sessions": decorated})


@router.get("/sessions/new", response_class=HTMLResponse)
def new_session_form(request: Request):
    return templates.TemplateResponse(request, "session_new.html", {})


@router.post("/sessions/new")
def create_session(
    video_path: str = Form(...),
    report_path: str = Form(...),
    gps_path: str = Form(""),
    video_id: str = Form(""),
    driver_mode: str = Form(""),
    route: str = Form(""),
    author: str = Form(""),
):
    video = Path(video_path).expanduser()
    report = Path(report_path).expanduser()
    if not video.exists():
        raise HTTPException(400, f"Video file not found: {video}")
    if not report.exists():
        raise HTTPException(400, f"Report file not found: {report}")
    gps = Path(gps_path).expanduser() if gps_path.strip() else None
    if gps and not gps.exists():
        raise HTTPException(400, f"GPS file not found: {gps}")

    parsed = parse_report(report)

    vid = (video_id or "").strip() or _derive_video_id(video)
    video_start_ms = _derive_video_start_ms(vid)

    db = get_db()
    session = ReportSession(
        id=None,
        video_path=str(video),
        report_path=str(report),
        video_id=vid,
        driver_mode=driver_mode.strip(),
        route=route.strip(),
        author=author.strip(),
        gps_path=str(gps) if gps else "",
        video_start_ms=video_start_ms,
    )
    sid = db.get_or_create_session(session)
    db.replace_flags(sid, parsed.flags)
    if gps is not None:
        try:
            points = parse_gps_csv(gps)
        except Exception:
            points = []
        db.replace_gps_points(sid, points)
    return RedirectResponse(url=f"/sessions/{sid}", status_code=303)


@router.get("/sessions/{sid}", response_class=HTMLResponse)
def view_session(request: Request, sid: int):
    db = get_db()
    session = db.get_session(sid)
    if session is None:
        raise HTTPException(404, "Session not found")
    flags = db.list_flags(sid)
    # Map flag_id -> latest annotation (per-flag), to render badges in the table.
    annotations = db.list_annotations(sid)
    latest_by_flag: dict[int, dict] = {}
    manual_annotations: list[dict] = []
    for a in annotations:
        if a["source"] != "manual":
            continue
        if a["flag_id"] is not None:
            latest_by_flag[int(a["flag_id"])] = a
        else:
            manual_annotations.append(a)
    # newest first in the manual list
    manual_annotations.sort(key=lambda r: r["id"], reverse=True)

    checklist = db.list_checklist(active_only=False)
    fault_codes = db.list_fault_codes(active_only=False)
    has_gps = len(db.list_gps_points(sid)) > 0
    return templates.TemplateResponse(request, "session_view.html", {"session": session,
            "flags": flags,
            "latest_by_flag": latest_by_flag,
            "manual_annotations": manual_annotations,
            "checklist": checklist,
            "fault_codes": fault_codes,
            "has_gps": has_gps,
            "fmt_mmss": seconds_to_mmss,
            "ma_fmt_mmss": seconds_to_mmss})


@router.post("/sessions/{sid}/delete")
def delete_session(sid: int):
    db = get_db()
    db.delete_session(sid)
    return RedirectResponse(url="/sessions", status_code=303)


@router.post("/sessions/{sid}/relocate-video")
def relocate_video(sid: int, video_path: str = Form(...)):
    p = Path(video_path).expanduser()
    if not p.exists():
        raise HTTPException(400, f"Video file not found: {p}")
    get_db().update_session_video_path(sid, str(p))
    return RedirectResponse(url=f"/sessions/{sid}", status_code=303)

