/* ROADMASTER map pane.
 * Loads GPS route + manual annotations for a session and renders on Leaflet
 * over CARTO Voyager tiles. Two-way comms with the page's <video> element:
 *   route/marker click   -> seek the video
 *   video timeupdate     -> reposition playhead marker (window._mapPlayhead)
 */
(function () {
  const COLORS = { TP: "#5fbf6f", FP: "#e26b6b", FN: "#e6a45f", Mis: "#a16fcf", TN: "#888" };

  let map = null;
  let routeLayer = null;
  let annotationLayer = null;
  let speedLayer = null;
  let playheadMarker = null;
  let routePoints = [];          // [{ts_ms, lat, lng, t}]
  let videoStartMs = null;
  let speedSignsLoaded = false;
  let speedVisible = true;

  function nearestIdx(latlng) {
    if (!routePoints.length) return -1;
    let best = 0, bestD = Infinity;
    for (let i = 0; i < routePoints.length; i++) {
      const p = routePoints[i];
      const dx = p.lat - latlng.lat, dy = p.lng - latlng.lng;
      const d = dx * dx + dy * dy;
      if (d < bestD) { bestD = d; best = i; }
    }
    return best;
  }

  function nearestRoutePointForTime(t) {
    if (!routePoints.length) return null;
    const targetMs = (videoStartMs ?? routePoints[0].ts_ms) + Math.round(t * 1000);
    let best = routePoints[0], bestD = Math.abs(best.ts_ms - targetMs);
    for (let i = 1; i < routePoints.length; i++) {
      const d = Math.abs(routePoints[i].ts_ms - targetMs);
      if (d < bestD) { bestD = d; best = routePoints[i]; }
    }
    return best;
  }

  async function initMap(sessionId) {
    const el = document.getElementById("map");
    if (!el || typeof L === "undefined") return;
    map = L.map(el).setView([57.71, 12.93], 14);
    L.tileLayer("https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png", {
      subdomains: "abcd", maxZoom: 20,
      attribution: "© OpenStreetMap contributors © CARTO",
    }).addTo(map);
    routeLayer = L.layerGroup().addTo(map);
    speedLayer = L.layerGroup().addTo(map);
    annotationLayer = L.layerGroup().addTo(map);

    const player = document.getElementById("player");

    const gps = await fetch(`/sessions/${sessionId}/gps.json`).then(r => r.json());
    videoStartMs = gps.video_start_ms ?? (gps.points[0] && gps.points[0].ts_ms) ?? null;
    routePoints = (gps.points || []).map(p => ({
      ts_ms: p.ts_ms, lat: p.lat, lng: p.lng,
      t: ((p.ts_ms - (videoStartMs ?? p.ts_ms)) / 1000),
    }));

    if (routePoints.length) {
      const latlngs = routePoints.map(p => [p.lat, p.lng]);
      const line = L.polyline(latlngs, { color: "#2e6fd6", weight: 5, opacity: 0.7 });
      line.on("click", e => {
        const idx = nearestIdx(e.latlng);
        if (idx >= 0 && player) { player.currentTime = routePoints[idx].t; }
      });
      routeLayer.addLayer(line);
      try { map.fitBounds(line.getBounds(), { padding: [20, 20] }); } catch (e) {}
    }

    const annotations = await fetch(`/sessions/${sessionId}/annotations.json`).then(r => r.json());
    for (const a of annotations) {
      const target = nearestRoutePointForTime(a.t);
      if (!target) continue;
      const fill = COLORS[a.cls] || "#666";
      const m = L.circleMarker([target.lat, target.lng], {
        radius: 8, color: "#222", weight: 1.5, fillColor: fill, fillOpacity: 0.9,
      });
      const mmss = (s) => {
        s = Math.max(0, Math.round(s));
        return String(Math.floor(s/60)).padStart(2,"0") + ":" + String(s%60).padStart(2,"0");
      };
      m.bindTooltip(
        `<b>CL${a.cl}: ${a.cls}</b><br>${mmss(a.t)}` + (a.comment ? `<br>${a.comment}` : ""),
        { sticky: true }
      );
      m.on("click", () => { if (player) { player.currentTime = a.t; } });
      annotationLayer.addLayer(m);
    }

    // Expose playhead updater for the page's video timeupdate hook.
    window._mapPlayhead = function (t) {
      const target = nearestRoutePointForTime(t);
      if (!target) return;
      if (!playheadMarker) {
        playheadMarker = L.circleMarker([target.lat, target.lng], {
          radius: 9, color: "#000", weight: 3, fillColor: "#ffeb3b", fillOpacity: 1.0,
        }).addTo(map);
      } else {
        playheadMarker.setLatLng([target.lat, target.lng]);
      }
    };

    // Speed signs from OSM Overpass — fetched lazily after route loads.
    loadSpeedSigns(sessionId);
    window._mapToggleSpeed = function (visible) {
      speedVisible = !!visible;
      if (!speedLayer) return;
      if (speedVisible) speedLayer.addTo(map); else map.removeLayer(speedLayer);
    };
  }

  function speedColor(kmh) {
    // Bucketed colors for visual scanability — slow=green, fast=red.
    if (kmh <= 30) return "#2e8b3a";
    if (kmh <= 50) return "#88a830";
    if (kmh <= 70) return "#dc9a26";
    if (kmh <= 90) return "#cf6a1f";
    return "#b03a2e";
  }

  async function loadSpeedSigns(sessionId) {
    if (speedSignsLoaded) return;
    speedSignsLoaded = true;
    try {
      const resp = await fetch(`/sessions/${sessionId}/speed-signs.json`);
      if (!resp.ok) {
        console.warn("speed-signs fetch failed:", resp.status);
        return;
      }
      const data = await resp.json();
      const signs = data.signs || [];
      for (const s of signs) {
        const icon = L.divIcon({
          className: "speed-sign",
          html: `<div style="background:#fff;color:${speedColor(s.speed)};border:2px solid ${speedColor(s.speed)};border-radius:50%;width:26px;height:26px;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:11px;font-family:sans-serif;box-shadow:0 1px 2px rgba(0,0,0,0.3)">${s.speed}</div>`,
          iconSize: [26, 26],
          iconAnchor: [13, 13],
        });
        const m = L.marker([s.lat, s.lng], { icon, interactive: false });
        speedLayer.addLayer(m);
      }
    } catch (e) {
      console.warn("speed-signs error:", e);
    }
  }

  // Expose
  window.initMap = initMap;
})();

