# === Auth wiring ===
# Order matters: SessionMiddleware must populate `request.session` before
# AuthMiddleware reads it. In Starlette, the LAST-added middleware is the
# OUTERMOST one (runs first on incoming requests), so we add AuthMiddleware
# first, SessionMiddleware second.
if APP_PASSWORD:
    if SESSION_SECRET == "dev-insecure-secret-change-me" and IS_PROD:
        logging.warning(
            "ROADMASTER_SESSION_SECRET is unset in production — "
            "session cookies are signed with a known default key."
        )
    app.add_middleware(AuthMiddleware)
    app.add_middleware(
        SessionMiddleware,
        secret_key=SESSION_SECRET,
        session_cookie="roadmaster_session",
        https_only=IS_PROD,
        same_site="lax",
        max_age=24 * 60 * 60,  # 24h
    )


