def login_form(request: Request, error: str = ""):
    return templates.TemplateResponse(
        request,
        "login.html",
        {"error": error, "auth_required": bool(APP_PASSWORD)},
    )


@app.post("/login")
def login_submit(request: Request, password: str = Form("")):
    if not APP_PASSWORD:
        # No password configured — log them in regardless.
        request.session["authenticated"] = True
        return RedirectResponse(url=f"{URL_PREFIX}/sessions", status_code=303)
    if password == APP_PASSWORD:
        request.session["authenticated"] = True
        return RedirectResponse(url=f"{URL_PREFIX}/sessions", status_code=303)
    # Wrong password — re-render with an error.
    return RedirectResponse(url=f"{URL_PREFIX}/login?error=1", status_code=303)


@app.get("/logout")
def logout(request: Request):
    request.session.clear()
    return RedirectResponse(url=f"{URL_PREFIX}/login", status_code=303)

