     x-data='{
        sessions: {{ available | tojson }},
        existingByPath: {{ existing_by_path | tojson }},
        videosDir: {{ (videos_dir or "")|tojson }},
        pickedId: "",
        showPaths: {{ "false" if available else "true" }},
        pick(id) {
          this.pickedId = id;
          const s = this.sessions.find(x => x.id === id);
          if (!s) return;
          this.$refs.video.value = s.video_path;
          this.$refs.report.value = s.report_path;
          this.$refs.gps.value = s.gps_path;
          this.$refs.videoId.value = s.id;
        },
        confirmIfDuplicate(e) {
          const path = (this.$refs.video.value || "").trim();
          if (!path) return;
          const existingId = this.existingByPath[path];
          if (existingId !== undefined && !confirm(
            `A session already exists for this video (session #${existingId}).\n\n` +
            `Create an additional session with the same video anyway?`)) {
            e.preventDefault();
          }
        }
     }'>

  {% if available %}
  <p class="text-sm text-slate-600 mb-3">
    Pick a session from the server library
    {% if videos_dir %}<span class="text-xs text-slate-500">({{ videos_dir }})</span>{% endif %}.
    The video, report, and GPS paths fill in automatically.
  </p>
  {% elif videos_dir %}
  <p class="text-sm text-slate-600 mb-3">
    No new sessions found in <code class="text-xs">{{ videos_dir }}</code>
    (every subfolder there is already in the DB, or none contain a <code class="text-xs">final_video.mp4</code>).
    You can still add one manually below.
  </p>
  {% else %}
  <p class="text-sm text-slate-600 mb-3">
    Paste absolute paths to files on this <strong>server's</strong> filesystem.
    Files are not uploaded.
  </p>
  {% endif %}

  <form method="post" action="{{ url_prefix }}/sessions/new" class="grid grid-cols-1 gap-3">

    {% if available %}
    <label class="grid gap-1 text-sm">
      <span class="font-medium">Session</span>
      <select required class="border rounded px-2 py-1.5 bg-white"
              x-model="pickedId" @change="pick(pickedId)">
        <option value="" disabled>— pick one —</option>
        {% for s in available %}
        <option value="{{ s.id }}">
          {{ s.id }}{% if not s.has_report %} (missing report){% endif %}{% if not s.has_gps %} (no GPS){% endif %}
        </option>
        {% endfor %}
      </select>
    </label>
    <button type="button" class="text-xs text-slate-500 underline w-fit"
            @click="showPaths = !showPaths">
      <span x-show="!showPaths">Show / edit paths (advanced)</span>
      <span x-show="showPaths">Hide paths</span>
    </button>
    {% endif %}

    <div x-show="showPaths" class="grid grid-cols-1 gap-3 {% if available %}border-l-2 border-slate-200 pl-4{% endif %}">
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Video file (.mp4 / .mov / .mkv / .avi)</span>
        <input name="video_path" x-ref="video" :required="showPaths" class="border rounded px-2 py-1.5"
               placeholder="/data/roadmaster/iteration_2/<id>/final_video.mp4" />
      </label>
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Negative report (.txt)</span>
        <input name="report_path" x-ref="report" :required="showPaths" class="border rounded px-2 py-1.5"
               placeholder="…/negative_report.txt" />
      </label>
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Location data CSV (optional, enables map)</span>
        <input name="gps_path" x-ref="gps" class="border rounded px-2 py-1.5"
               placeholder="…/<id>_LocationData.csv" />
      </label>
    </div>

    {# Always-rendered inputs that the dropdown writes into. When the paths block above
       is hidden, x-show=false sets display:none on the wrapper but the inputs still
       submit. We hide the wrapper, not the inputs themselves, so submitted values persist. #}

    <div class="grid grid-cols-2 gap-3">
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Video ID</span>
        <input name="video_id" x-ref="videoId" class="border rounded px-2 py-1.5"
               placeholder="auto-derived from folder name" />
      </label>
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Driver mode</span>
        <input name="driver_mode" class="border rounded px-2 py-1.5" placeholder="e.g. Safe, Error" />
      </label>
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Route</span>
        <input name="route" class="border rounded px-2 py-1.5" placeholder="e.g. Borås (route 2)" />
      </label>
      <label class="grid gap-1 text-sm">
        <span class="font-medium">Author</span>
        <input name="author" class="border rounded px-2 py-1.5" placeholder="your name"
               x-data x-init="$el.value = localStorage.getItem('roadmaster_author') || ''" />
      </label>
    </div>
    <div class="flex gap-2 mt-2">
      <button class="bg-slate-700 text-white text-sm px-3 py-1.5 rounded hover:bg-slate-800">Create session</button>
      <a href="{{ url_prefix }}/sessions" class="text-sm text-slate-600 px-3 py-1.5">Cancel</a>
    </div>
  </form>
</div>
{% endblock %}

