"""OpenStreetMap helpers — currently fetches speed-limit-tagged elements within
the bounding box of a session's GPS route via the public Overpass API.

Results are cached in memory per (rounded) bbox to avoid hammering Overpass.
"""
from __future__ import annotations

import math
import time
from threading import Lock

import httpx
from fastapi import APIRouter, HTTPException

from app.database import get_db

router = APIRouter()

OVERPASS = "https://overpass-api.de/api/interpreter"
# Overpass returns 406 Not Acceptable for the default httpx UA — they rate-limit
# / block bot-looking clients. Identify ourselves with a real string per the
# Overpass etiquette docs (https://wiki.openstreetmap.org/wiki/Overpass_API).
_HEADERS = {
    "User-Agent": "ROADMASTER-Validation-Tool/0.1 (https://screens.ri.se/roadmaster)",
}
CACHE_TTL_S = 60 * 60  # 1 hour
_cache: dict[tuple, tuple[float, list[dict]]] = {}
_cache_lock = Lock()


def _bbox_from_points(points: list[dict]) -> tuple[float, float, float, float]:
    """Return (south, west, north, east) bounding box for the GPS sample list,
    expanded slightly so we catch signs immediately off-route."""
    lats = [float(p["lat"]) for p in points]
    lngs = [float(p["lng"]) for p in points]
    pad_lat = 0.0015  # ~150 m
    pad_lng = 0.0030
    return (min(lats) - pad_lat, min(lngs) - pad_lng,
            max(lats) + pad_lat, max(lngs) + pad_lng)


def _round(v: float, decimals: int = 3) -> float:
    return round(v, decimals)


# Max distance from any GPS sample for a sign to count as "on route".
# 60 m allows for the road's width plus GPS jitter while excluding signs on
# parallel/cross streets.
_ROUTE_RADIUS_M = 60.0


def _meters(lat1: float, lng1: float, lat2: float, lng2: float) -> float:
    """Haversine distance in meters between two lat/lng points."""
    R = 6371000.0
    phi1 = math.radians(lat1)
    phi2 = math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlam = math.radians(lng2 - lng1)
    a = (math.sin(dphi / 2) ** 2
         + math.cos(phi1) * math.cos(phi2) * math.sin(dlam / 2) ** 2)
    return 2 * R * math.asin(math.sqrt(a))


def _filter_near_route(signs: list[dict], points: list[dict],
                       max_m: float = _ROUTE_RADIUS_M) -> list[dict]:
    """Drop signs whose nearest GPS sample is farther than ``max_m``.

    A bbox-equirectangular pre-filter would be faster but with ~10^3 points and
    ~10^2 signs the loop here is plenty fast and avoids approximation bugs.
    """
    if not points:
        return signs
    out: list[dict] = []
    for s in signs:
        slat = float(s["lat"])
        slng = float(s["lng"])
        # Cheap squared-degree pre-filter to skip far-away points.
        # 0.001 deg ~= 100 m at our latitude; threshold a bit looser than max_m.
        max_deg = (max_m / 111000.0) * 1.5
        candidates = [p for p in points
                      if abs(float(p["lat"]) - slat) < max_deg
                      and abs(float(p["lng"]) - slng) < max_deg]
        if not candidates:
            continue
        nearest = min(_meters(slat, slng, float(p["lat"]), float(p["lng"]))
                      for p in candidates)
        if nearest <= max_m:
            out.append(s)
    return out


def _query_overpass(s: float, w: float, n: float, e: float) -> list[dict]:
    """Pull speed-limit-bearing elements from Overpass. Returns a flat list of
    ``{lat, lng, speed, kind}`` dicts. ``speed`` is the ``maxspeed`` tag value
    (typically a number in km/h, but may be ``walk``/``signals``/etc. — we only
    keep numeric ones for display)."""
    query = f"""
[out:json][timeout:25];
(
  node["maxspeed"]({s},{w},{n},{e});
  node["traffic_sign"~"maxspeed",i]({s},{w},{n},{e});
  way["maxspeed"]({s},{w},{n},{e});
);
out tags center 200;
""".strip()
    try:
        r = httpx.post(OVERPASS, data={"data": query}, headers=_HEADERS, timeout=30.0)
        r.raise_for_status()
        data = r.json()
    except Exception as ex:
        # Surface a helpful error but don't crash — the map will just not show signs.
        raise HTTPException(502, f"Overpass error: {ex}")

    out: list[dict] = []
    for el in data.get("elements", []):
        tags = el.get("tags") or {}
        speed_raw = (tags.get("maxspeed") or "").strip()
        # Only emit numeric speeds (drop "walk", "none", "signals", etc.).
        try:
            speed = int(float(speed_raw.split()[0]))
        except (ValueError, IndexError, AttributeError):
            continue
        if el.get("type") == "node":
            lat, lng = el.get("lat"), el.get("lon")
        else:
            c = el.get("center") or {}
            lat, lng = c.get("lat"), c.get("lon")
        if lat is None or lng is None:
            continue
        out.append({"lat": float(lat), "lng": float(lng), "speed": speed,
                    "kind": el.get("type")})
    return out


