def _ways_with_speed(elements: list[dict]) -> list[dict]:
    """Filter to ways with a parseable numeric maxspeed. Each result has
    ``geometry`` (list of {lat, lon}), ``speed`` (km/h), and ``layer``
    (int, for stacked-road disambiguation)."""
    out = []
    for el in elements:
        if el.get("type") != "way":
            continue
        tags = el.get("tags") or {}
        speed = _parse_speed_kmh(tags.get("maxspeed"))
        geom = el.get("geometry") or []
        if speed is None or not geom:
            continue
        # Bridges default to layer=1 if explicit layer missing — common in
        # data where mappers tagged ``bridge=yes`` but forgot the layer.
        layer = _parse_layer(tags.get("layer"))
        if layer == 0 and tags.get("bridge") not in (None, "no"):
            layer = 1
        if layer == 0 and tags.get("tunnel") not in (None, "no"):
            layer = -1
        out.append({"id": el.get("id"), "speed": speed,
                    "geometry": geom, "layer": layer})
    return out

