    sid: int,
    field: str = Form(...),
    value: str = Form(""),
):
    """Update one of {route, driver_mode, author} on a session row.

    Only the named field is touched; everything else on the session row
    (and *all* related rows — annotations, flags, GPS) is left alone.
    Used by the inline-editable cells on the sessions list page.
    """
    if field not in {"route", "driver_mode", "author"}:
        raise HTTPException(400, f"Refusing to update field {field!r}")
    db = get_db()
    if db.get_session(sid) is None:
        raise HTTPException(404)
    kw = {field: value.strip()}
    db.update_session_metadata(sid, **kw)
    # 204 keeps HTMX happy (no swap needed; the input already shows the new value).
    return Response(status_code=204)

