  function seekTo(seconds) {
    if (player) { player.currentTime = seconds; }   // never auto-play
  }
  function seekRel(delta) { if (player) player.currentTime = Math.max(0, player.currentTime + delta); }
  function toggleMute() {
    if (!player) return;
    player.muted = !player.muted;
    document.getElementById('mute-btn').textContent = player.muted ? '🔇' : '🔊';
  }
  player?.addEventListener('timeupdate', () => {
    document.getElementById('player-time').textContent = fmt(player.currentTime * 1000);
    if (window._mapPlayhead) window._mapPlayhead(player.currentTime);
  });
  document.addEventListener('keydown', (e) => {
    if (['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)) return;
    if (e.key === ' ')      { e.preventDefault(); player.paused ? player.play() : player.pause(); }
    if (e.key.toLowerCase() === 'm') toggleMute();
    if (e.key === 'ArrowLeft')  seekRel(e.shiftKey ? -10 : -5);
    if (e.key === 'ArrowRight') seekRel(e.shiftKey ?  10 :  5);
  });
</script>

{% if has_gps %}
<script>window.URL_PREFIX = "{{ url_prefix }}";</script>
<script src="{{ url_prefix }}/static/js/map.js"></script>

