PW='Saphira23456!'
TS=$(date +%Y%m%d-%H%M%S)
echo "=== Backup ==="
echo "$PW" | sudo -S -p '' cp /etc/nginx/sites-available/screens.ri.se /etc/nginx/sites-available/screens.ri.se.bak.$TS
echo "Backup: /etc/nginx/sites-available/screens.ri.se.bak.$TS"

echo
echo "=== Write new config ==="
echo "$PW" | sudo -S -p '' bash -c "cat > /etc/nginx/sites-available/screens.ri.se <<'CONF'
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name screens.ri.se;

    ssl_certificate /etc/nginx/ssl/screens.ri.se.crt;
    ssl_certificate_key /etc/nginx/ssl/screens.ri.se.key;

    # --- ConAI LLM Tester (sub-path /conai) ---
    location = /conai {
        return 301 /conai/;
    }

    location /conai/ {
        alias /opt/conai/dist/;
        index index.html;
        try_files \$uri \$uri/ /conai/index.html;
    }

    location /conai/api/ {
        proxy_pass http://127.0.0.1:3001/api/;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 300s;
        proxy_send_timeout 300s;
        proxy_buffering off;
        client_max_body_size 10m;
    }
    # --- end ConAI ---

    # --- ROADMASTER Validation Tool (sub-path /roadmaster) ---
    location = /roadmaster {
        return 301 /roadmaster/;
    }

    location /roadmaster/ {
        proxy_pass http://127.0.0.1:3002/;
