        proxy_set_header X-Forwarded-Prefix /roadmaster;
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
        proxy_buffering off;
        client_max_body_size 50m;
    }
    # --- end ROADMASTER ---

    # --- ConAI Methods study-design page (static, basic auth) ---
    location = /conaimethods {
