$('bz-fit').onclick = fitBoardZoom;

// ---- Fullscreen mode for option cards ------------------------------------
// "Fullskärm" hides all chrome and lets `#palette` (the option cards) take the
// whole viewport. Uses the browser Fullscreen API so the URL bar / tabs also
// hide. Esc exits via the fullscreenchange listener; an X button does the same.
(function setupCardsFullscreen() {
  const exitBtn = document.createElement('button');
  exitBtn.id = 'fs-exit-btn';
  exitBtn.type = 'button';
  exitBtn.textContent = '✕ Avsluta fullskärm (Esc)';
  document.body.appendChild(exitBtn);

  const indicator = document.createElement('div');
  indicator.id = 'fs-step-indicator';
  document.body.appendChild(indicator);

  function syncIndicator() {
    const step = ($('palette-step') || {}).textContent || '';
    const title = ($('palette-title') || {}).textContent || '';
    indicator.innerHTML = `${step} · <strong>${title}</strong>`;
  }

  function enter() {
    syncIndicator();
    document.body.classList.add('fullscreen-cards');
    const el = document.documentElement;
    const req = el.requestFullscreen || el.webkitRequestFullscreen || el.msRequestFullscreen;
    if (req) req.call(el).catch(() => {/* user denied / unsupported — body class still applies */});
    // Cards auto-fit on enter so a workshop crowd can read them immediately.
    if (typeof fitBoardZoom === 'function') setTimeout(fitBoardZoom, 30);
  }
  function exit() {
    document.body.classList.remove('fullscreen-cards');
    const ex = document.exitFullscreen || document.webkitExitFullscreen || document.msExitFullscreen;
    if (document.fullscreenElement && ex) ex.call(document).catch(() => {});
  }

  $('bz-fullscreen').onclick = () =>
    document.body.classList.contains('fullscreen-cards') ? exit() : enter();
  exitBtn.onclick = exit;
  document.addEventListener('fullscreenchange', () => {
    if (!document.fullscreenElement) document.body.classList.remove('fullscreen-cards');
  });
  // Keep the floating step indicator in sync when the user navigates while in
  // fullscreen (e.g. via keyboard if we add it later, or via the browser back).
  const obs = new MutationObserver(() => {
    if (document.body.classList.contains('fullscreen-cards')) syncIndicator();
  });
  const ps = $('palette-step'); if (ps) obs.observe(ps, { childList: true, characterData: true, subtree: true });
  const pt = $('palette-title'); if (pt) obs.observe(pt, { childList: true, characterData: true, subtree: true });
})();

// Collapse/expand the step strip
$('strip-toggle').onclick = () => { state.stripCollapsed = !state.stripCollapsed; applyStripCollapsed(); saveState(true); };

